import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"","description":"面向零基础中文读者的 AI 综合知识库，按 AI 基础、LLM、Prompt、RAG、Agent、工具与 AI 绘画路线系统学习。","frontmatter":{"layout":"home","description":"面向零基础中文读者的 AI 综合知识库，按 AI 基础、LLM、Prompt、RAG、Agent、工具与 AI 绘画路线系统学习。","hero":{"name":"AI 综合知识库","text":"从基础原理到应用实践","tagline":"按主题查找，也可沿学习地图入门——不堆链接，不追热点，全部从零讲起","image":{"src":"/assets/home-hero.png","alt":"AI 知识库主视觉"},"actions":[{"theme":"brand","text":"查看学习地图","link":"/guide/getting-started"},{"theme":"alt","text":"查看术语表","link":"/glossary"}]},"features":[{"title":"AI 基础与大模型原理（8 页）","icon":{"src":"/assets/icon-concepts.png","alt":"AI 基础与大模型图标","width":48,"height":48},"details":"从 AI、机器学习和神经网络，到 Token、Embedding、Transformer、推理解码与训练对齐，共 8 页，适合建立原理框架或按概念查阅。"},{"title":"应用实践（4 页）","icon":{"src":"/assets/icon-tools.png","alt":"应用实践图标","width":48,"height":48},"details":"围绕 Prompt、RAG 与 Agent、工作流和常用工具，共 4 页，帮助把模型能力变成可验证、可复用的任务流程。"},{"title":"AI 绘画（5 页）","icon":{"src":"/assets/icon-workflow.png","alt":"AI 绘画图标","width":48,"height":48},"details":"理解底模、模型组成、扩散原理、模型生态与 LoRA，共 5 页，可以独立作为图像生成专题查阅。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788335970000}'),i={name:"index.md"};function s(n,e,l,h,d,g){return t(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="这份知识库适合谁" tabindex="-1">这份知识库适合谁 <a class="header-anchor" href="#这份知识库适合谁" aria-label="Permalink to &quot;这份知识库适合谁&quot;">​</a></h2><p>面向刚接触 AI 的中文读者：你可能听过大语言模型、Token、Embedding、RAG、Agent、Stable Diffusion、ComfyUI、LoRA 这些词，但说不清它们之间是什么关系，也不知道该先学哪个。</p><p>本站按主题组织知识。每页都以一个明确的结论开头，配上前置知识、学习目标、对比表和自测问题，既可以围绕一个目标组合阅读，也可以直接当查阅手册使用。</p><p>第一次访问又不确定从哪里开始，可以先看<a href="/guide/getting-started">学习地图</a>；已经有明确问题时，直接进入对应主题或使用顶部搜索。术语拿不准时查<a href="/glossary">术语表</a>。</p><h2 id="按主题浏览" tabindex="-1">按主题浏览 <a class="header-anchor" href="#按主题浏览" aria-label="Permalink to &quot;按主题浏览&quot;">​</a></h2><ul><li><strong>AI 基础</strong>：从 <a href="/ai/basics">AI 基础概念</a> 开始，按需补充 <a href="/ai/machine-learning">机器学习入门</a> 和 <a href="/ai/neural-networks">神经网络直觉</a>。</li><li><strong>大模型原理</strong>：从 <a href="/llm/basics">大模型入门</a> 建立总览，再查 Token、Transformer、推理解码或训练对齐。</li><li><strong>应用实践</strong>：从 <a href="/prompting/basics">Prompt 入门</a> 进入，也可以直接查 <a href="/llm/rag-agent">RAG 与 Agent</a>、<a href="/workflows/workflow-vs-template">工作流和模板区别</a>或<a href="/tools/common-tools">常用工具</a>。</li><li><strong>AI 绘画</strong>：从 <a href="/concepts/base-model">底模是什么</a> 认识核心对象，再按问题查组成、原理、模型生态与 LoRA。</li><li><strong>资源</strong>：通过 <a href="/resources/websites">常用网站</a> 和 <a href="/resources/tutorials">精选教程</a>继续学习，遇到陌生词随时查<a href="/glossary">术语表</a>。</li></ul><p>这些主题不是必须依次完成的课程。想快速解决问题可以直接查对应页面；想系统入门，则在<a href="/guide/getting-started">学习地图</a>里选择一条符合目标的路线。</p><h2 id="内容边界" tabindex="-1">内容边界 <a class="header-anchor" href="#内容边界" aria-label="Permalink to &quot;内容边界&quot;">​</a></h2><p>本站按公开发布口径编写：</p><ul><li>不提供盗版模型、侵权素材、绕过平台规则或规避安全限制的方法。</li><li>不以成人内容、攻击性用途、违法采集数据或滥用自动化为教程主线。</li><li>使用模型、数据、素材和 API 时，优先查看许可证、模型卡、隐私条款和平台规则；本站不替代这些文件的约束。</li><li>页面中出现的具体产品只作为类别举例，不代表推荐；使用时以当时的官方说明为准。</li></ul><p>本站之外的内容随时可能更新，遇到与本站描述不一致的地方，以对应项目和平台的最新官方文档为准。</p>',11)])])}const f=a(i,[["render",s]]);export{p as __pageData,f as default};
